def frogMinEnergy(heights):
    n = len(heights)
    if n == 1:
        return 0
    prev2, prev1 = 0, abs(heights[1] - heights[0])    # best(0), best(1)
    for i in range(2, n):
        cur = min(prev1 + abs(heights[i] - heights[i - 1]),
                  prev2 + abs(heights[i] - heights[i - 2]))
        prev2, prev1 = prev1, cur
    return prev1
